def policy(obs, P):
    x, y, vx, vy, angle, ang_v, leg_left, leg_right = obs
    if angle > P['a_thr']:
        return 1
    if angle < -P['a_thr_neg']:
        return 1
    if leg_left > 0.5 or leg_right > 0.5:
        if vy > P['vy_leg'] and abs(angle) < P['a_thr']*2.0:
            return 0
    if ang_v < -P['av_thr']:
        return 1
    if ang_v > P['av_thr_pos']:
        return 3
    if vy < P['vy_thr']:
        return 2
    if vx < -P['vx_thr']:
        return 3
    if vx > P['vx_thr']:
        return 1
    return 0
